import type { Person } from '../../domain/directory'
import type { ProfilePatch, SelfProfile } from '../../domain/profile'

interface ProfileSDK {
  getSelfUserInfo: () => Promise<unknown>
  setSelfInfo: (params: ProfilePatch) => Promise<unknown>
  getUsersInfo: (ids: string[]) => Promise<unknown>
  getSpecifiedFriendsInfo: (params: { friendUserIDList: string[], filterBlack: boolean }) => Promise<unknown>
  updateFriends: (params: { friendUserIDs: string[], remark: string }) => Promise<unknown>
  getBlackList: () => Promise<unknown>
  addBlack: (params: { toUserID: string }) => Promise<unknown>
  removeBlack: (id: string) => Promise<unknown>
}
export function createProfileService (getSDK: () => Promise<ProfileSDK>, unwrap: (value: unknown) => unknown) {
  function person (value: unknown): Person {
    if (!value || typeof value !== 'object' || !('userID' in value) || typeof value.userID !== 'string')
      throw new Error('OpenIM 用户资料响应格式不正确')
    return value as Person
  }
  function list (value: unknown): Person[] {
    const data = unwrap(value)
    if (!Array.isArray(data))
      throw new Error('OpenIM 用户列表响应格式不正确')
    return data.map(person)
  }
  return {
    self: async () => person(unwrap(await (await getSDK()).getSelfUserInfo())) as SelfProfile,
    person: async (id: string) => {
      const sdk = await getSDK()
      const friends = list(await sdk.getSpecifiedFriendsInfo({ friendUserIDList: [id], filterBlack: false }))
      const friend = friends.find(user => user.userID === id)
      if (friend)
        return { ...friend, isFriend: true }
      const users = list(await sdk.getUsersInfo([id]))
      const user = users.find(item => item.userID === id)
      return user && { ...user, isFriend: false }
    },
    blacklist: async () => list(await (await getSDK()).getBlackList()),
    updateSelf: async (nickname: string, faceURL: string) => {
      nickname = nickname.trim()
      faceURL = faceURL.trim()
      if (!nickname)
        throw new Error('昵称不能为空')
      if (faceURL && !faceURL.startsWith('data:image/') && !/^https?:\/\/[^\s]+$/.test(faceURL))
        throw new Error('头像地址必须是 http 或 https 图片地址')
      return (await getSDK()).setSelfInfo({ nickname, faceURL })
    },
    muteNotifications: async (muted: boolean) => (await getSDK()).setSelfInfo({ globalRecvMsgOpt: muted ? 2 : 0 }),
    remark: async (id: string, remark: string) => {
      const sdk = await getSDK()
      const friends = list(await sdk.getSpecifiedFriendsInfo({ friendUserIDList: [id], filterBlack: false }))
      if (!friends.some(user => user.userID === id))
        throw new Error('仅好友可设置好友备注')
      return sdk.updateFriends({ friendUserIDs: [id], remark: remark.trim() })
    },
    block: async (id: string, blocked: boolean) => {
      const sdk = await getSDK()
      return blocked ? sdk.addBlack({ toUserID: id }) : sdk.removeBlack(id)
    },
  }
}

import { draftStorage } from '../storage/draft-storage'

let scope = ''
export function getDraftStorageScope () {
  return scope
}
export function setDraftStorageScope (server: string) {
  scope = server
}
function draftKey (userID: string, conversationID: string) {
  return `offline-product:im-composer:v2:${encodeURIComponent(scope)}:${encodeURIComponent(userID)}:${encodeURIComponent(conversationID)}`
}
interface DraftRecord { text?: string, mentions?: string[] }
async function readRecord (key: string): Promise<DraftRecord> {
  const value = await draftStorage.getItem(key)
  if (!value)
    return {}
  const parsed: unknown = JSON.parse(value)
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed))
    throw new Error('本地草稿无法读取，请重试')
  return parsed as DraftRecord
}
export async function readLocalDraft (userID: string, conversationID: string) {
  return (await readRecord(draftKey(userID, conversationID))).text
}
const writes = new Map<string, Promise<unknown>>()
function writeRecord (key: string, update: (previous: DraftRecord) => DraftRecord) {
  const pending = (writes.get(key) || Promise.resolve()).catch(() => undefined).then(async () => {
    const previous = await readRecord(key)
    await draftStorage.setItem(key, JSON.stringify(update(previous)))
  })
  writes.set(key, pending)
  void pending.finally(() => {
    if (writes.get(key) === pending)
      writes.delete(key)
  }).catch(() => undefined)
  return pending
}
export async function writeLocalDraft (userID: string, conversationID: string, text: string) {
  if (text.length > 100000)
    throw new Error('草稿过长，暂时无法保存，请缩短后重试')
  const key = draftKey(userID, conversationID)
  await writeRecord(key, previous => ({ ...previous, text }))
}
export async function readDraftMentions (userID: string, conversationID: string) {
  const record = await readRecord(draftKey(userID, conversationID))
  return Array.isArray(record.mentions) && record.mentions.every(id => typeof id === 'string') ? record.mentions : []
}
export async function writeDraftMentions (userID: string, conversationID: string, memberIDs: string[]) {
  const key = draftKey(userID, conversationID)
  await writeRecord(key, previous => ({ ...previous, mentions: [...new Set(memberIDs)] }))
}
export async function clearDeliveredDraft (userID: string, conversationID: string) {
  // Keep an explicit empty record so an SDK cleanup failure cannot resurrect delivered text.
  await writeRecord(draftKey(userID, conversationID), () => ({ text: '', mentions: [] }))
}

